    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Penalize resource imbalance
    let imbalance_penalty = (cpu_norm - ram_norm).abs() * 10.0; // Increased penalty weight

    // Normalize residuals
    let cpu_score = node_residual_cpu as f64;
    let ram_score = node_residual_ram as f64;

    // Dynamic horizon awareness
    let step_fraction = step_index as f64 / total_jobs as f64;
    let dynamic_penalty = if step_fraction < 0.5 { 0.1 } else { 0.2 }; // Adjusted penalty value

    // Lookahead awareness (k=2)
    let next_job_fits_cpu = node_residual_cpu >= next_job_cpu + job_cpu;
    let next_job_fits_ram = node_residual_ram >= next_job_ram + job_ram;
    let lookahead_penalty = if next_job_fits_cpu && next_job_fits_ram { 0.0 } else { 1.0 }; // Increased penalty value

    // Non-linear conditionals for compaction
    let compactness_score = if node_residual_cpu < node_capacity_cpu / 2.0 || node_residual_ram < node_capacity_ram / 2.0 {
        -5.0 * (node_residual_cpu + node_residual_ram) as f64
    } else {
        0.0
    };

    // Combine scores
    let score = cpu_score + ram_score - imbalance_penalty + dynamic_penalty + lookahead_penalty + compactness_score;
    score
}

