pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Penalize resource imbalance
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Normalize residuals
    let cpu_score = node_residual_cpu as f64;
    let ram_score = node_residual_ram as f64;

    // Dynamic horizon awareness
    let step_fraction = step_index as f64 / total_jobs as f64;
    let dynamic_penalty = if step_fraction < 0.5 { 0.1 } else { 0.0 };

    // Lookahead anticipation (k=2)
    let next_job_fits_cpu = node_residual_cpu >= next_job_cpu + job_cpu;
    let next_job_fits_ram = node_residual_ram >= next_job_ram + job_ram;
    let lookahead_bonus = if next_job_fits_cpu && next_job_fits_ram { 0.5 } else { 0.0 };

    // Non-linear conditionals
    let cpu_usage_ratio = node_capacity_cpu as f64 - node_residual_cpu as f64;
    let ram_usage_ratio = node_capacity_ram as f64 - node_residual_ram as f64;
    let non_linear_penalty = (cpu_usage_ratio * cpu_norm).powi(2) + (ram_usage_ratio * ram_norm).powi(2);

    // Combine scores
    let score = cpu_score + ram_score - imbalance_penalty - dynamic_penalty + lookahead_bonus - non_linear_penalty;
    score
}
